    let mut chosenMonIndices: [u16_0; 4] = [0; 4];
    let mut friendship: u8_0 = 0;
    let mut level: u8_0 = SetTentPtrsGetLevel();
    let mut fixedIV: u8_0 = 0 as u8_0;
    let mut bfMonCount: u8_0 = 0;
