#[unsafe(no_mangle)]
pub unsafe extern "C" fn FacilityClassToGraphicsId(mut facilityClass: u8_0) -> u8_0 {
    let mut trainerObjectGfxId: u8_0 = 0;
    let mut i: u8_0 = 0;
    i = 0 as u8_0;
    while (i as size_t)
        < (::core::mem::size_of::<[u8_0; 30]>() as usize)
            .wrapping_div(::core::mem::size_of::<u8_0>() as usize) as size_t
    {
        if gTowerMaleFacilityClasses[i as usize] as ::core::ffi::c_int
            == facilityClass as ::core::ffi::c_int
        {
            break;
        }
        i = i.wrapping_add(1);
    }
    if i as size_t
        != (::core::mem::size_of::<[u8_0; 30]>() as usize)
            .wrapping_div(::core::mem::size_of::<u8_0>() as usize) as size_t
    {
        trainerObjectGfxId = gTowerMaleTrainerGfxIds[i as usize];
        return trainerObjectGfxId;
    }
    i = 0 as u8_0;
    while (i as size_t)
        < (::core::mem::size_of::<[u8_0; 20]>() as usize)
            .wrapping_div(::core::mem::size_of::<u8_0>() as usize) as size_t
    {
        if gTowerFemaleFacilityClasses[i as usize] as ::core::ffi::c_int
            == facilityClass as ::core::ffi::c_int
        {
            break;
        }
        i = i.wrapping_add(1);
    }
    if i as size_t
        != (::core::mem::size_of::<[u8_0; 20]>() as usize)
            .wrapping_div(::core::mem::size_of::<u8_0>() as usize) as size_t
    {
        trainerObjectGfxId = gTowerFemaleTrainerGfxIds[i as usize];
        return trainerObjectGfxId;
    } else {
        return 7 as u8_0
    };
}
