pub unsafe extern "C" fn ValidateBattleTowerRecord(mut recordId: u8_0) -> bool32 {
    let mut i: s32 = 0;
    let mut record: *mut u32_0 = (&raw mut (*if !gSaveBlock2Ptr.is_null() {
        gSaveBlock2Ptr
    } else {
        &raw mut gNativeMemory as *mut ::core::ffi::c_uchar as *mut SaveBlock2
    })
        .frontier
        .towerRecords as *mut EmeraldBattleTowerRecord)
        .offset(recordId as isize) as *mut EmeraldBattleTowerRecord as *mut u32_0;
    let mut checksum: u32_0 = 0 as u32_0;
    let mut hasData: u32_0 = 0 as u32_0;
    i = 0 as ::core::ffi::c_int as s32;
    while (i as usize)
        < (232 as usize).wrapping_div(::core::mem::size_of::<u32_0>() as usize)
    {
        checksum = checksum
            .wrapping_add(
                *if !record.is_null() {
                    record
                } else {
                    &raw mut gNativeMemory as *mut ::core::ffi::c_uchar as *mut u32_0
                }
                    .offset(i as isize),
            );
        hasData
            |= *if !record.is_null() {
                record
            } else {
                &raw mut gNativeMemory as *mut ::core::ffi::c_uchar as *mut u32_0
            }
                .offset(i as isize);
        i += 1;
    }
    if checksum == 0 as u32_0 && hasData == 0 as u32_0 {
        return 0 as bool32
    } else if (*if !gSaveBlock2Ptr.is_null() {
        gSaveBlock2Ptr
    } else {
        &raw mut gNativeMemory as *mut ::core::ffi::c_uchar as *mut SaveBlock2
    })
        .frontier
        .towerRecords[recordId as usize]
        .checksum != checksum
    {
        ClearBattleTowerRecord(
            (&raw mut (*if !gSaveBlock2Ptr.is_null() {
                gSaveBlock2Ptr
            } else {
                &raw mut gNativeMemory as *mut ::core::ffi::c_uchar as *mut SaveBlock2
            })
                .frontier
                .towerRecords as *mut EmeraldBattleTowerRecord)
                .offset(recordId as isize) as *mut EmeraldBattleTowerRecord,
        );
        return 0 as bool32;
    } else {
        return 1 as bool32
    };
}
